function summarize(rows) {
  // 합계 기준 컬럼 이름 후보
  const amountKeys = ["금액", "매출", "합계", "총액", "실매출", "정산금액", "수수료", "순이익"];
  const numeric = k => !isNaN(parseFloat(k)) && isFinite(k);

  const totals = {};
  let count = 0;

  for (const r of rows) {
    const key = r["항목"] || r["구분"] || r["채널"] || r["상품"] || "기타";
    for (const aKey of amountKeys) {
      if (r[aKey] && numeric(r[aKey].replace(/[^0-9.-]/g, ""))) {
        const v = parseFloat(r[aKey].replace(/[^0-9.-]/g, ""));
        totals[aKey] = (totals[aKey] || 0) + v;
        count++;
        break;
      }
