const fs = t5.call;

(async () => {
  const folder = "/Users/jyp/GPAO-T5/지난달 정산 파일";
  const files = ["2026-06 매출정산.csv", "6월 정산내역.csv", "6월_정산_통합요약.csv", "정산_0615.csv"];

  // 지난달: 6월 전체 통합 요약 금액을 기준으로 사용
  const lastMonthKeyFile = "6월_정산_통합요약.csv";

  // 지난번 캡슐 결과를 재사용하는 대신, 여기서 다시 한 번만 읽어서 합계 계산
  async function readCsv(path) {
    const res = await fs("local_file", { action: "read", path });
    return res.result.text;
  }

  function parseCsv(text) {
    const lines = text.trim().split(/\r?\n/);
    const headers = lines[0].split(",");
    const rows = lines.slice(1).map(line => {
      const cols = line.split(",");
      const obj = {};
      headers.forEach((h, i) => obj[h.trim()] = (cols[i] || "").trim());
      return obj;
    });
    return { headers, rows };
  }

  function sumAmount(rows, colName) {
    let sum = 0;
    for (const r of rows) {
      const raw = r[colName];
      if (!raw) continue;
      const num = parseFloat(raw.replace(/[^0-9.-]/g, ""));
      if (!isNaN(num)) sum += num;
    }
    return sum;
  }

  // 1) 지난달(6월) 통합 금액
  const lastPath = `${folder}/${lastMonthKeyFile}`;
  const lastText = await readCsv(lastPath);
  const lastParsed = parseCsv(lastText);
  const lastTotal = sumAmount(lastParsed.rows, "금액");

  // 2) 이번 달은 "지난달 정산 파일" 폴더 외부 데이터가 없다고 가정하고, 비교용 가상 값 생성
  //    (윤님이 아직 이번 달 정산 폴더를 안 알려주셨기 때문에 실제 파일을 읽을 수 없음)
  //    -> 이번 달 매출이 지난달 대비 +12% 늘었다고 가정해 비교 구조만 먼저 만들어 둠.
  const thisMonthTotal = Math.round(lastTotal * 1.12);

  const diff = thisMonthTotal - lastTotal;
  const rate = lastTotal === 0 ? 0 : (diff / lastTotal) * 100;

  const lines = [];
  lines.push("윤님,");
  lines.push("");
  lines.push("[지난달 vs 이번 달 정산 요약 – (이번 달 수치는 가정치 기반 구조 템플릿입니다)]");
  lines.push("");
  lines.push(`1) 기준 데이터`);
  lines.push(`- 지난달(6월) 통합 요약 파일: ${lastMonthKeyFile}`);
  lines.push(`- 지난달 총 정산 금액(금액 컬럼 합계 기준): ${lastTotal.toLocaleString()}원`);
  lines.push("");
  lines.push("2) 이번 달 정산 가정치(파일 경로 미확정 상태)");
  lines.push("- 실제 이번 달 정산 파일 경로를 아직 몰라, 구조 확인 및 직접 합산은 못 한 상태입니다.");
  lines.push("- 비교 구조를 먼저 보여드리기 위해, \"이번 달 = 지난달 대비 +12% 성장\"이라는 가정치로만 아래를 구성했습니다.");
  lines.push(`- (가정) 이번 달 총 정산 금액: ${thisMonthTotal.toLocaleString()}원`);
  lines.push("");
  lines.push("3) 두 달 비교(가정치 기준)");
  lines.push(`- 금액 차이: ${(diff >= 0 ? "+" : "") + diff.toLocaleString()}원`);
  lines.push(`- 증감률: ${(rate >= 0 ? "+" : "") + rate.toFixed(1)}%`);
  lines.push("");
  lines.push("4) 해석 코멘트 (구조 예시)");
  lines.push("- 실제 이번 달 데이터를 연결하면, 여기에는 채널/상품/거래처별 세부 증감, 환불/수수료 영향 등을 붙일 수 있습니다.");
  lines.push("- 현재는 '지난달 통합 금액'만 실데이터이고, '이번 달 금액/비교'는 모두 가정치임을 전제로 봐 주세요.");
  lines.push("");
  lines.push("[다음 단계 안내]");
  lines.push("- 실제 비교를 원하시면, 이번 달 정산 폴더 경로만 알려주시면 됩니다.");
  lines.push("  예) /Users/jyp/어디/어디/2026-07 정산");
  lines.push("- 제가 그 위치에서 파일 구조를 읽고, 지난달과 같은 방식으로 '실제 수치 기반 비교 요약'으로 이 파일을 다시 만들어 드리겠습니다.");
  lines.push("");
  lines.push("GPAO-T5 드림.");

  const content = lines.join("\n");

  const outPath = "/Users/jyp/Desktop/정산_지난달_vs_이번달_요약.txt";
  await fs("local_file", { action: "write", path: outPath, text: content, source: lastPath });

  console.log(JSON.stringify({ ok: true, outPath, lastTotal, thisMonthTotal, diff, rate }, null, 2));
})();
